"""Bilingual executive study, compact card and existing accordion hierarchy."""
from pathlib import Path
import json,shutil,html
from bs4 import BeautifulSoup
from PIL import Image
ROOT=Path(__file__).resolve().parents[1];PORT=ROOT.parent/'portifolio-sellerscope-publish';REPO='https://github.com/lucasmenghi/creditscope';ETL='https://github.com/lucasmenghi/Case_Default_Risk'
def main():
    m=json.loads((ROOT/'reports/metrics.json').read_text());d=json.loads((ROOT/'reports/data_manifest.json').read_text());f=json.loads((ROOT/'reports/frozen_config.json').read_text());n=m['selected'];scenarios=json.loads((ROOT/'reports/capacity_scenarios.json').read_text())
    Image.open(ROOT/'assets/executive-cover.png').convert('RGB').save(ROOT/'assets/creditscope-cover.webp',quality=90,method=6)
    css=(ROOT/'assets/study.css').read_text()+'\n:root{--ink:#202833;--teal:#d81334;--cream:#fff;--navy:#f7f7f8;} .hero{color:#202833;background:#f7f7f8;} .hero a,.hero .eyebrow{color:#d81334;} .hero .lead{color:#4c5662;} .hero .button{border-color:#d81334;} .hero-art{aspect-ratio:1672/941;} .stats{grid-template-columns:repeat(4,minmax(0,1fr));} @media(max-width:760px){.stats{grid-template-columns:repeat(2,minmax(0,1fr));}}'
    for pt in [True,False]:
        def t(a,b):return a if pt else b
        filename=t('creditscope.html','creditscope-en.html');other=t('creditscope-en.html','creditscope.html');listing=t('projetos.html','projects.html')
        intro=t('Da ingestão Oracle à classificação de risco: um estudo com aplicações reais da Home Credit, probabilidades calibradas e priorização para análise humana.','From Oracle ingestion to risk classification: a study using real Home Credit applications, calibrated probabilities and prioritization for human review.')
        problem=t('Como priorizar uma fila de análise quando a capacidade é limitada? O modelo estima a probabilidade de dificuldade de pagamento segundo o TARGET da competição. A fonte define atraso superior a X dias em pelo menos uma das primeiras Y parcelas, sem divulgar X e Y. O estudo apoia investigação de risco; não determina aprovação, taxa de juros ou limite de crédito.','How should a limited review capacity be prioritized? The model estimates payment difficulty under the competition TARGET. The source defines a delay exceeding X days in at least one of the first Y installments, without disclosing X and Y. The study supports risk investigation; it does not determine approval, interest rates or credit limits.')
        data=t('307.511 aplicações rotuladas; 24.825 positivas (8,07%). O arquivo exportado pelo seu ETL contém os mesmos clientes e alvos. A camada analítica recupera campos já presentes na tabela HC_APPLICATION e reconstrói os agregados históricos a partir dos CSVs originais. O conjunto application_test sem rótulos não entra na avaliação.','307,511 labeled applications; 24,825 positive cases (8.07%). The existing ETL export contains matching customer IDs and labels. The analytical layer retrieves fields already present in HC_APPLICATION and rebuilds historical aggregates from original CSV files. Unlabeled application_test is not used for evaluation.')
        audit=t('Corte no dia relativo zero: crédito e atualização do bureau, decisão anterior, vencimento e pagamento de parcelas devem ser anteriores ou iguais à solicitação. Foram excluídos 17 registros de bureau e 2.905 registros de parcelas futuros ou sem data. Gênero e identificadores ficam fora das features; a sentinela 365243 de emprego é tratada como ausente. As tabelas continuam sendo snapshots retrospectivos: esses filtros não comprovam disponibilidade de todos os campos em uma operação real.','Relative-day-zero cutoff: bureau credit and update, previous decision, installment due date and payment must be on or before the application. Seventeen bureau records and 2,905 future or undated installment records were excluded. Gender and identifiers are excluded from features; employment sentinel 365243 is treated as missing. Tables remain retrospective snapshots: these filters do not establish operational availability of every field.')
        method=t(f'Quatro candidatos: duas regressões logísticas e dois LightGBM. Seleção por average precision em desenvolvimento: {f["selected"]}. Clientes separados em treino (184.506), desenvolvimento (30.751), calibração (30.751), política (15.375) e teste (46.128). Imputação e escala ajustadas no treino; calibração sigmoid em outro grupo; limiar no percentil 80 da política. Teste pontuado somente após congelamento. Não há calendário global de solicitações: a validação é estratificada por cliente, não temporal.',f'Four candidates: two logistic regressions and two LightGBM models. Selected by development average precision: {f["selected"]}. Separate customers for training (184,506), development (30,751), calibration (30,751), policy (15,375) and testing (46,128). Training-only imputation/scaling; sigmoid calibration on another group; policy-score 80th percentile threshold. Final testing follows freezing. No global application calendar is provided: this is stratified customer validation, not temporal validation.')
        limits=t('Uma semente e uma separação; desempenho histórico, sem teste temporal, ROI ou redução de perdas demonstrados. Os scores externos são anonimizados e pouco explicáveis. Idade permanece entre as entradas. A exclusão de gênero não garante equidade: há variáveis proxy. O repositório traz uma auditoria descritiva por gênero, que não prova justiça ou adequação regulatória. Antes de um piloto, validar disponibilidade, tempo, drift, calibração, impactos e política de crédito com especialistas.','One seed and one split; historical performance without temporal testing, demonstrated ROI or loss reduction. External scores are anonymized and hard to explain. Age remains an input. Excluding gender does not establish fairness: proxy variables exist. The repository includes a descriptive gender audit, which does not establish fairness or regulatory suitability. Before a pilot, validate availability, time, drift, calibration, impacts and credit policy with specialists.')
        rows=''.join(f'<tr><td>{label}</td><td>{x["average_precision"]:.3f}</td><td>{x["roc_auc"]:.3f}</td><td>{x["ks"]:.3f}</td><td>{x["brier"]:.3f}</td><td>{x["precision_at20"]:.1%}</td><td>{x["recall_at20"]:.1%}</td><td>{x["lift_at20"]:.2f}×</td></tr>' for label,x in [(f['selected'],n),('Logistic baseline',m['logistic_baseline'])])
        body=f'''<a class="skip" href="#main">{t('Ir para conteúdo','Skip to content')}</a><header class="hero"><div class="wrap"><nav><a href="LISTING">← {t('Portfólio','Portfolio')}</a><div><a href="{other}">{t('English','Português')}</a><a href="{REPO}" target="_blank" rel="noopener">GitHub ↗</a></div></nav><img class="hero-art" src="COVER" width="1672" height="941" alt="Home Credit Case — Credit Risk Intelligence"><p class="eyebrow">CREDITSCOPE / HOME CREDIT CASE / CLASSIFICATION</p><h1>{t('Do dado ao risco de crédito','From data to credit risk')}</h1><p class="lead">{intro}</p><a class="button" href="#results">{t('Explorar resultados','Explore results')}</a><a class="button" href="{REPO}" target="_blank" rel="noopener">{t('Ver projeto','View project')}</a></div></header><main class="wrap" id="main"><section><p class="eyebrow">01 / BUSINESS UNDERSTANDING</p><h2>{t('Priorizar a análise com evidências','Prioritize review with evidence')}</h2><p>{problem}</p></section><section><p class="eyebrow">02 / DATA UNDERSTANDING &amp; PREPARATION</p><h2>{t('Continuidade do seu projeto de ingestão','Building on the ingestion project')}</h2><p>{data}</p><p>{audit}</p><a class="button" href="{ETL}" target="_blank" rel="noopener">{t('Ver ingestão original','Original ingestion project')} ↗</a></section><section><p class="eyebrow">03 / MODELING</p><h2>{t('Comparar, calibrar e congelar','Compare, calibrate and freeze')}</h2><p>{method}</p><figure><img class="plot" src="FIGURESdevelopment.png" loading="lazy" alt="Development average precision by candidate"></figure></section><section id="results"><p class="eyebrow">04 / EVALUATION</p><h2>{t('Resultado em clientes reservados','Results on held-out customers')}</h2><div class="table-wrap"><table><thead><tr><th>{t('Modelo','Model')}</th><th>AP</th><th>ROC AUC</th><th>KS</th><th>Brier ↓</th><th>Precision@20%</th><th>Recall@20%</th><th>Lift@20%</th></tr></thead><tbody>{rows}</tbody></table></div><p class="note">AP = average precision. {t('Prevalência no teste','Test prevalence')}: {m['test_positive_rate']:.1%}. {t('Métricas calculadas em 46.128 clientes que não participaram da seleção, calibração ou política. Uma partição, sem intervalos de confiança.','Metrics computed on 46,128 customers excluded from selection, calibration and policy. One split, no confidence intervals.')}</p><figure><img class="plot" src="FIGURESprecision_recall.png" loading="lazy" alt="Final-test precision and recall"></figure><figure><img class="plot" src="FIGUREScalibration.png" loading="lazy" alt="Calibrated probabilities and observed outcomes"></figure><p>{t('Limiar congelado','Frozen threshold')}: {n['threshold']:.3f}; {t('parcela sinalizada','flagged share')}: {n['queue_rate']:.1%}; precision: {n['precision']:.1%}; recall: {n['recall']:.1%}. {t('Esse limiar não garante uma fila de 20% no futuro.','This threshold does not guarantee a future 20% queue.')}</p><figure><img class="plot" src="FIGURESrisk_deciles.png" loading="lazy" alt="Observed payment difficulty by score decile"></figure></section><section><p class="eyebrow">05 / HISTORICAL CAPACITY SCENARIO</p><h2>{t('Capacidade de análise e concentração de risco','Review capacity and risk concentration')}</h2><p>{t('Selecione uma fração dos clientes de teste pelo ranking. Esse diagnóstico histórico é separado do limiar congelado e não garante o resultado de intervenções reais.','Choose a fraction of test customers by ranking. This historical diagnostic is separate from the frozen threshold and does not guarantee real intervention outcomes.')}</p><label for="capacity">{t('Capacidade de análise','Review capacity')}</label><select id="capacity">{''.join(f'<option value="{r["capacity"]}" '+('selected' if r['capacity']==20 else '')+f'>{r["capacity"]}%</option>' for r in scenarios)}</select><div class="stats">{''.join(f'<article class="stat"><output class="number" id="{key}"></output><small>{label}</small></article>' for key,label in [('queue',t('Clientes selecionados','Selected customers')),('identified',t('Positivos identificados','Positive cases identified')),('precision',t('Precisão da fila','Queue precision')),('lift',t('Lift vs. seleção aleatória','Lift vs. random selection'))])}</div></section><section><p class="eyebrow">06 / LIMITATIONS &amp; NEXT STEPS</p><h2>{t('Limites e próximo passo','Limits and next step')}</h2><p>{limits}</p><figure><img class="plot" src="FIGURESsubgroups.png" loading="lazy" alt="Descriptive gender subgroup audit"></figure><a class="button" href="{REPO}/blob/main/notebooks/01_home_credit_case.ipynb">Notebook ↗</a><a class="button" href="{REPO}/blob/main/docs/model_card.md">Model card ↗</a></section></main><footer class="wrap"><p class="note">Lucas Menghi · {t('Case independente, sem vínculo ou endosso da Home Credit. Capa conceitual gerada com IA; logo da fonte oficial. Gráficos calculados com os dados reais.','Independent case, no Home Credit affiliation or endorsement. AI-generated conceptual cover; logo from the official source. Charts computed from real data.')} <a href="https://www.kaggle.com/competitions/home-credit-default-risk/data">{t('Dados originais','Original data')}</a> · <a href="https://www.homecredit.cz/dokumenty-ke-stazeni/obecne-informace">{t('Logo oficial','Official logo')}</a></p></footer><script>const scenarios={json.dumps(scenarios)};function update(){{const row=scenarios.find(x=>x.capacity===Number(document.getElementById('capacity').value)).selected;for(const key of ['queue','identified'])document.getElementById(key).textContent=row[key].toLocaleString('{t('pt-BR','en-US')}');document.getElementById('precision').textContent=(100*row.precision).toFixed(1)+'%';document.getElementById('lift').textContent=row.lift.toFixed(2)+'×';}}document.getElementById('capacity').addEventListener('change',update);update();</script>'''
        for repo in [True,False]:
            content=f'<!DOCTYPE html><html lang="{t("pt-BR","en")}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Home Credit Case | Lucas Menghi</title><meta name="description" content="{html.escape(intro)}"><style>{css}</style></head><body>'+body.replace('COVER','../assets/creditscope-cover.webp' if repo else '../images/thumbs/creditscope-cover.webp').replace('FIGURES','../reports/figures/' if repo else '../images/creditscope/').replace('LISTING','https://lucasmenghi.github.io/portifolio/projects/'+listing if repo else listing)+'</body></html>'
            (ROOT/'docs'/filename if repo else PORT/'projects'/filename).write_text(content,encoding='utf-8')
        card=f'''<article class="col-6 work-item project-card"><h4 class="project-title">CreditScope — Home Credit Case</h4><a class="image fit thumb" href="{filename}"><img src="../images/thumbs/creditscope-cover.webp" alt="Home Credit Case — Credit Risk Intelligence" loading="lazy"/></a><div class="project-content"><h5>{t('Contexto','Context')}:</h5><p>{t('Classificação de dificuldade de pagamento para priorizar análise humana de risco de crédito, completando o projeto de ingestão Oracle.','Payment-difficulty classification for prioritizing human credit-risk review, extending the Oracle ingestion project.')}</p><h5>{t('Abordagem','Approach')}:</h5><p>{t('307.511 aplicações reais; quatro candidatos; histórico auditado; calibração e política separadas; teste reservado por cliente.','307,511 real applications; four candidates; audited history; separate calibration and policy; held-out customers.')}</p><h5>{t('Resultado','Result')}:</h5><p>ROC AUC: {n['roc_auc']:.3f}; AP: {n['average_precision']:.3f}. {t('Ao analisar 20% dos clientes','Reviewing 20% of customers')}: recall {n['recall_at20']:.1%}; lift {n['lift_at20']:.2f}×. {t('Avaliação histórica, sem validação temporal.','Historical evaluation, without temporal validation.')}</p><p class="project-tags">Python · Oracle · LightGBM · Classification · Calibration · CRISP-DM · Streamlit</p></div><a class="button project-button" href="{filename}">{t('Ver estudo','Read case study')} →</a><a class="button project-button" href="{REPO}" target="_blank" rel="noopener">{t('Ver projeto','View project')} →</a></article>'''
        for port in [PORT,ROOT.parent/'portifolio']:
            path=port/'projects'/listing;soup=BeautifulSoup(path.read_text(encoding='utf-8'),'html.parser');section=soup.find(id=t('classificacao','classification'))
            for existing in section.select('article.project-card'):
                if 'CreditScope' in existing.get_text():existing.decompose()
            section.select_one('.project-grid').append(BeautifulSoup(card,'html.parser').article);section.select_one('.subarea-count').string=f'{len(section.select("article.project-card"))} '+t('projetos publicados','published projects');cat=section.find_parent(class_='project-category');cat.select_one('.category-count').string=f'{len(cat.select("article.project-card"))} '+t('projetos','projects');path.write_text(str(soup),encoding='utf-8')
    dest=PORT/'images/creditscope';dest.mkdir(exist_ok=True)
    for file in (ROOT/'reports/figures').glob('*.png'):shutil.copy2(file,dest/file.name)
    shutil.copy2(ROOT/'assets/creditscope-cover.webp',PORT/'images/thumbs/creditscope-cover.webp');primary=ROOT.parent/'portifolio'
    for name in ['creditscope.html','creditscope-en.html']:shutil.copy2(PORT/'projects'/name,primary/'projects'/name)
    shutil.copytree(dest,primary/'images/creditscope',dirs_exist_ok=True);shutil.copy2(ROOT/'assets/creditscope-cover.webp',primary/'images/thumbs/creditscope-cover.webp');print('Bilingual study and compact classification cards built.')
if __name__=='__main__':main()
